import 'dart:convert';
import 'dart:io';

import 'package:operit2/core/proxy/generated/CoreProxyModels.g.dart';

/// Generated by Core's markdown_render_fixture example, without a Dart parser.
final semanticMarkdownFixtures =
    (jsonDecode(
              File(
                'test/fixtures/markdown_semantic_events.json',
              ).readAsStringSync(),
            )
            as List)
        .cast<Map<String, dynamic>>();

Future<List<MarkdownStreamEvent>> splitSemanticMarkdownFixture(
  String source,
) async => semanticMarkdownEvents(source);

List<MarkdownStreamEvent> semanticMarkdownEvents(String source) {
  final fixture = semanticMarkdownFixtures.singleWhere(
    (item) => item['source'] == source,
  );
  return (fixture['events'] as List)
      .cast<Map<String, dynamic>>()
      .map(
        (event) => MarkdownStreamEvent(
          chatId: event['chatId'] as String,
          eventType: event['type'] as String,
          value: event['value'] as String?,
          id: event['id'] as String?,
          blockId: event['blockId'] as int?,
          inlineId: event['inlineId'] as int?,
          parentBlockId: event['parentBlockId'] as int?,
          nodeType: event['nodeType'] as String?,
          headerLevel: event['headerLevel'] as int?,
          xml: null,
        ),
      )
      .toList();
}
